var n=`1204-sopa-de-frijoles`;var t=`world-1204`;var a=`HN`;var r=`central-america-caribbean`;var s=4;var o=609;var l={en:`Sopa de Frijoles`,ua:`Гондураський квасолевий суп`};var d={en:`Sopa de Frijoles is a dish from Honduras featuring kidney beans, yellow onion, garlic, green bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Гондураський квасолевий суп, страва кухні країни Гондурас з такими основними складниками: червона квасоля кідні, жовта цибуля, часник, зелений солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Soak the dried beans in ample clean cold water for about 480 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 480 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:480,i:[[`kidney-beans`,420,`g`],[`water`,1200,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`garlic`,5,`clove`],[`green-bell-pepper`,170,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`chicken-stock`,700,`ml`],[`ground-cumin`,6,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,25,`g`],[`lime`,1,`pcs`]]}];var u={slug:n,id:t,country:`HN`,region:r,servings:4,minutes:609,title:l,text:d,steps:g};export{a as country,u as default,t as id,o as minutes,r as region,s as servings,n as slug,g as steps,d as text,l as title};